def max_common_factor(a, b):
    """
    计算两个数的最大公约数，返回两个数的最大公约数。
    """
    if a == 0 or b == 0:
        return 0
    if a > b:
        a, b = b, a
    if a < 2:
        return a
    if b < 2:
        return b
    while a % b != 0:
        a, b = b, a % b
    return a

